DISTRICT_MAP = {}
for div, dists in BANGLADESH_GEO.items():
    for dist, info in dists.items():
        DISTRICT_MAP[dist.lower()] = {
            'division': div,
            'district': dist,
            'lat': info['lat'],
            'lon': info['lon'],
            'upazilas': info['upazilas']
        }

def get_district_info(district_name):
    if not district_name:
        return None
    return DISTRICT_MAP.get(district_name.strip().lower())

def get_district_center(district_name):
    info = get_district_info(district_name)
    if info:
        return info['lat'], info['lon']
    return None, None
